impl Solution{pub fn longest_increasing_path(a:Vec<Vec<i32>>)->i32{if a.is_empty(){return 0}fn f(a:&Vec<Vec<i32>>,r:usize,c:usize,dp:&mut Vec<Vec<i32>>)->i32{if dp[r][c]!=0{return dp[r][c]}let d=[(1,0),(-1,0),(0,1),(0,-1)];let mut b=1;for &(x,y)in&d{let i=r as i32+x;let j=c as i32+y;if i>=0&&j>=0&&i<a.len()as i32&&j<a[0].len()as i32&&a[i as usize][j as usize]>a[r][c]{b=b.max(1+f(a,i as usize,j as usize,dp));}}dp[r][c]=b;b}let mut dp=vec![vec![0;a[0].len()];a.len()];let mut b=0;for i in 0..a.len(){for j in 0..a[0].len(){b=b.max(f(&a,i,j,&mut dp));}}b}}
